"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4369],{4369:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-tragedy-of-y.png\\"\\n          title=\\"Y의 비극\\"\\n          author=\\"엘러리 퀸\\"\\n          publisher=\\"검은숲\\"\\n          publishedDate=\\"2013-05-13\\"\\n          isbn=\\"9788952768711\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n```세계 3대 추리 소설``` 중 한 작품이다.  \\n워낙 유명한 작품이지만, 생각보다 손에 잡히지 않아서 읽지 않았다가 알라딘 중고서점에서 우연히 눈에 띄어 읽기를 결심했었다.  \\n<br>\\n사건이 흘러가는 방향과 탐정의 추리가 억지스럽지 않고 납득할 만하다.  \\n또한 반전의 범인과 이를 해결하는 탐정 <mark>드루리 레인</mark>의 방식이 독자들에게 많은 호감을 샀을 것이다.  \\n<br>\\n하지만 한편, 이렇게 사건이 처리되는 것이 맞나? 하는 생각이 든다.  \\n마치 ```오리엔트 특급 살인```과 비슷한 처리 방식.  \\n<br>\\n<mark>비뚤어진 집</mark>과 유사하다."}')}}]);